95	/// Translate one environment variable from Value to String
96	///
97	/// Returns Ok(None) if the env var is not
98	pub fn env_to_string(
99	env_name: &str,
100	value: &Value,
101	engine_state: &EngineState,
102	stack: &Stack,
103	) -> Result<String, ShellError> {
104	match get_converted_value(engine_state, stack, env_name, value, "to_string") {
105	ConversionResult::Ok(v) => Ok(v.coerce_into_string()?),
106	ConversionResult::ConversionError(e) => Err(e),
107	ConversionResult::CellPathError => match value.coerce_string() {
108	Ok(s) => Ok(s),
109	Err(_) => {
110	if env_name == ENV_PATH_NAME {
111	// Try to convert PATH/Path list to a string
112	match value {
113	Value::List { vals, .. } => {
114	let paths = vals
115	.iter()
116	.map(Value::coerce_str)
117	.collect::<Result<Vec<_>, _>>()?;
118	
119	match std::env::join_paths(paths.iter().map(AsRef::as_ref)) {
120	Ok(p) => Ok(p.to_string_lossy().to_string()),
121	Err(_) => Err(ShellError::EnvVarNotAString {
122	envvar_name: env_name.to_string(),
123	span: value.span(),
124	}),
125	}
126	}
127	_ => Err(ShellError::EnvVarNotAString {
128	envvar_name: env_name.to_string(),
129	span: value.span(),
130	}),
131	}
132	} else {
133	Err(ShellError::EnvVarNotAString {
134	envvar_name: env_name.to_string(),
135	span: value.span(),
136	})
137	}
138	}
139	},
140	}
