361	func (c *fileConfig) Aliases() (*AliasConfig, error) {
362	// The complexity here is for dealing with either a missing or empty aliases key. It's something
363	// we'll likely want for other config sections at some point.
364	entry, err := c.FindEntry("aliases")
365	var nfe *NotFoundError
366	notFound := errors.As(err, &nfe)
367	if err != nil && !notFound {
368	return nil, err
369	}
370	
371	toInsert := []*yaml.Node{}
372	
373	keyNode := entry.KeyNode
374	valueNode := entry.ValueNode
375	
376	if keyNode == nil {
377	keyNode = &yaml.Node{
378	Kind:  yaml.ScalarNode,
379	Value: "aliases",
380	}
381	toInsert = append(toInsert, keyNode)
382	}
383	
384	if valueNode == nil || valueNode.Kind != yaml.MappingNode {
385	valueNode = &yaml.Node{
386	Kind:  yaml.MappingNode,
387	Value: "",
388	}
389	toInsert = append(toInsert, valueNode)
390	}
