430	func (c *fileConfig) Hosts() ([]string, error) {
431	entries, err := c.hostEntries()
432	if err != nil {
433	return nil, err
434	}
435	
436	hostnames := []string{}
437	for _, entry := range entries {
438	hostnames = append(hostnames, entry.Host)
439	}
440	
441	sort.SliceStable(hostnames, func(i, j int) bool { return hostnames[i] == ghinstance.Default() })
442	
443	return hostnames, nil
444	}
