446	func (c *fileConfig) makeConfigForHost(hostname string) *HostConfig {
447	hostRoot := &yaml.Node{Kind: yaml.MappingNode}
448	hostCfg := &HostConfig{
449	Host:      hostname,
450	ConfigMap: ConfigMap{Root: hostRoot},
451	}
452	
453	var notFound *NotFoundError
454	hostsEntry, err := c.FindEntry("hosts")
455	if errors.As(err, &notFound) {
456	hostsEntry.KeyNode = &yaml.Node{
457	Kind:  yaml.ScalarNode,
458	Value: "hosts",
459	}
460	hostsEntry.ValueNode = &yaml.Node{Kind: yaml.MappingNode}
461	root := c.Root()
462	root.Content = append(root.Content, hostsEntry.KeyNode, hostsEntry.ValueNode)
463	} else if err != nil {
464	panic(err)
465	}
466	
467	hostsEntry.ValueNode.Content = append(hostsEntry.ValueNode.Content,
468	&yaml.Node{
469	Kind:  yaml.ScalarNode,
470	Value: hostname,
471	}, hostRoot)
472	
473	return hostCfg
474	}
475	
476	func (c *fileConfig) parseHosts(hostsEntry *yaml.Node) ([]*HostConfig, error) {
477	hostConfigs := []*HostConfig{}
478	
479	for i := 0; i < len(hostsEntry.Content)-1; i = i + 2 {
480	hostname := hostsEntry.Content[i].Value
481	hostRoot := hostsEntry.Content[i+1]
482	hostConfig := HostConfig{
483	ConfigMap: ConfigMap{Root: hostRoot},
484	Host:      hostname,
485	}
486	hostConfigs = append(hostConfigs, &hostConfig)
487	}
488	
489	if len(hostConfigs) == 0 {
490	return nil, errors.New("could not find any host configurations")
491	}
492	
493	return hostConfigs, nil
494	}
495	
496	func defaultFor(key string) string {
497	// we only have a set default for one setting right now
498	switch key {
499	case "git_protocol":
500	return defaultGitProtocol
501	case "prompt":
502	return PromptsEnabled
503	default:
504	return ""
505	}
506	}
