12	jv jv_load_file(const char* filename, int raw) {
13	struct stat sb;
14	int fd = open(filename, O_RDONLY);
15	if (fd == -1) {
16	return jv_invalid_with_msg(jv_string_fmt("Could not open %s: %s",
17	filename,
18	strerror(errno)));
19	}
20	if (fstat(fd, &sb) == -1 || S_ISDIR(sb.st_mode)) {
21	close(fd);
22	return jv_invalid_with_msg(jv_string_fmt("Could not open %s: %s",
23	filename,
24	"It's a directory"));
25	}
26	FILE* file = fdopen(fd, "r");
27	struct jv_parser* parser = NULL;
28	jv data;
29	if (!file) {
30	close(fd);
31	return jv_invalid_with_msg(jv_string_fmt("Could not open %s: %s",
32	filename,
33	strerror(errno)));
34	}
35	if (raw) {
36	data = jv_string("");
37	} else {
38	data = jv_array();
39	parser = jv_parser_new(0);
40	}
41	
42	// To avoid mangling UTF-8 multi-byte sequences that cross the end of our read
43	// buffer, we need to be able to read the remainder of a sequence and add that
44	// before appending.
45	const int max_utf8_len = 4;
46	char buf[4096+max_utf8_len];
47	while (!feof(file) && !ferror(file)) {
48	size_t n = fread(buf, 1, sizeof(buf)-max_utf8_len, file);
49	int len = 0;
50	
51	if (n == 0)
52	continue;
53	if (jvp_utf8_backtrack(buf+(n-1), buf, &len) && len > 0 &&
54	!feof(file) && !ferror(file)) {
55	n += fread(buf+n, 1, len, file);
56	}
57	
58	if (raw) {
59	data = jv_string_append_buf(data, buf, n);
60	} else {
61	jv_parser_set_buf(parser, buf, n, !feof(file));
62	jv value;
63	while (jv_is_valid((value = jv_parser_next(parser))))
64	data = jv_array_append(data, value);
65	if (jv_invalid_has_msg(jv_copy(value))) {
66	jv_free(data);
67	data = value;
68	break;
69	}
70	}
71	}
