22	    // Creates a usage string for display. This happens just after all arguments were parsed, but before
23	    // any subcommands have been parsed (so as to give subcommands their own usage recursively)
24	    pub(crate) fn create_usage_with_title(&self, used: &[Id]) -> String {
25	        debug!("Usage::create_usage_with_title");
26	        let mut usage = String::with_capacity(75);
27	        usage.push_str("USAGE:\n    ");
28	        usage.push_str(&*self.create_usage_no_title(used));
29	        usage
30	    }
31	
32	    // Creates a usage string (*without title*) if one was not provided by the user manually.
33	    pub(crate) fn create_usage_no_title(&self, used: &[Id]) -> String {
34	        debug!("Usage::create_usage_no_title");
35	        if let Some(u) = self.p.app.usage_str {
36	            String::from(&*u)
37	        } else if used.is_empty() {
38	            self.create_help_usage(true)
39	        } else {
40	            self.create_smart_usage(used)
41	        }
42	    }
43	
44	    // Creates a usage string for display in help messages (i.e. not for errors)
45	    pub(crate) fn create_help_usage(&self, incl_reqs: bool) -> String {
46	        debug!("Usage::create_help_usage; incl_reqs={:?}", incl_reqs);
47	        let mut usage = String::with_capacity(75);
48	        let name = self
49	            .p
50	            .app
51	            .usage
52	            .as_ref()
53	            .unwrap_or_else(|| self.p.app.bin_name.as_ref().unwrap_or(&self.p.app.name));
54	        usage.push_str(&*name);
55	        let req_string = if incl_reqs {
56	            self.get_required_usage_from(&[], None, false)
57	                .iter()
58	                .fold(String::new(), |a, s| a + &format!(" {}", s)[..])
59	        } else {
60	            String::new()
61	        };
62	
63	        let flags = self.needs_flags_tag();
64	        if flags && !self.p.is_set(AS::UnifiedHelpMessage) {
65	            usage.push_str(" [FLAGS]");
66	        } else if flags {
67	            usage.push_str(" [OPTIONS]");
68	        }
69	        if !self.p.is_set(AS::UnifiedHelpMessage)
70	            && self
71	                .p
72	                .app
73	                .get_opts_with_no_heading()
74	                .any(|o| !o.is_set(ArgSettings::Required) && !o.is_set(ArgSettings::Hidden))
75	        {
76	            usage.push_str(" [OPTIONS]");
77	        }
78	
79	        usage.push_str(&req_string[..]);
80	
81	        let has_last = self
82	            .p
83	            .app
84	            .get_positionals()
85	            .any(|p| p.is_set(ArgSettings::Last));
86	        // places a '--' in the usage string if there are args and options
87	        // supporting multiple values
88	        if self
89	            .p
90	            .app
91	            .get_opts_with_no_heading()
92	            .any(|o| o.is_set(ArgSettings::MultipleValues))
93	            && self
94	                .p
95	                .app
96	                .get_positionals()
97	                .any(|p| !p.is_set(ArgSettings::Required))
98	            && !(self.p.app.has_visible_subcommands()
99	                || self.p.is_set(AS::AllowExternalSubcommands))
100	            && !has_last
101	        {
102	            usage.push_str(" [--]");
103	        }
104	        let not_req_or_hidden = |p: &Arg| {
105	            (!p.is_set(ArgSettings::Required) || p.is_set(ArgSettings::Last))
106	                && !p.is_set(ArgSettings::Hidden)
107	        };
108	        if self.p.app.get_positionals().any(not_req_or_hidden) {
109	            if let Some(args_tag) = self.get_args_tag(incl_reqs) {
110	                usage.push_str(&*args_tag);
111	            } else {
112	                usage.push_str(" [ARGS]");
113	            }
114	            if has_last && incl_reqs {
115	                let pos = self
116	                    .p
117	                    .app
118	                    .get_positionals()
119	                    .find(|p| p.is_set(ArgSettings::Last))
120	                    .expect(INTERNAL_ERROR_MSG);
121	                debug!("Usage::create_help_usage: '{}' has .last(true)", pos.name);
122	                let req = pos.is_set(ArgSettings::Required);
123	                if req
124	                    && self
125	                        .p
126	                        .app
127	                        .get_positionals()
128	                        .any(|p| !p.is_set(ArgSettings::Required))
129	                {
130	                    usage.push_str(" -- <");
131	                } else if req {
132	                    usage.push_str(" [--] <");
133	                } else {
134	                    usage.push_str(" [-- <");
135	                }
136	                usage.push_str(&*pos.name_no_brackets());
137	                usage.push('>');
138	                usage.push_str(pos.multiple_str());
139	                if !req {
140	                    usage.push(']');
141	                }
142	            }
143	        }
144	
145	        // incl_reqs is only false when this function is called recursively
146	        if self.p.app.has_visible_subcommands() && incl_reqs
147	            || self.p.is_set(AS::AllowExternalSubcommands)
148	        {
149	            let placeholder = self.p.app.subcommand_placeholder.unwrap_or("SUBCOMMAND");
150	            if self.p.is_set(AS::SubcommandsNegateReqs) || self.p.is_set(AS::ArgsNegateSubcommands)
151	            {
152	                usage.push_str("\n    ");
153	                if !self.p.is_set(AS::ArgsNegateSubcommands) {
154	                    usage.push_str(&*self.create_help_usage(false));
155	                } else {
156	                    usage.push_str(&*name);
157	                }
158	                usage.push_str(" <");
159	                usage.push_str(placeholder);
160	                usage.push('>');
161	            } else if self.p.is_set(AS::SubcommandRequired)
162	                || self.p.is_set(AS::SubcommandRequiredElseHelp)
163	            {
164	                usage.push_str(" <");
165	                usage.push_str(placeholder);
166	                usage.push('>');
167	            } else {
168	                usage.push_str(" [");
169	                usage.push_str(placeholder);
170	                usage.push(']');
171	            }
172	        }
173	        usage.shrink_to_fit();
174	        debug!("Usage::create_help_usage: usage={}", usage);
175	        usage
176	    }
