179	    fn validate_conflicts(&self, matcher: &ArgMatcher) -> ClapResult<()> {
180	        debug!("Validator::validate_conflicts");
181	
182	        self.validate_exclusive(matcher)?;
183	
184	        let mut conflicts = Conflicts::new();
185	        for arg_id in matcher
186	            .arg_names()
187	            .filter(|arg_id| matcher.contains_explicit(arg_id) && self.p.app.find(arg_id).is_some())
188	        {
189	            debug!("Validator::validate_conflicts::iter: id={:?}", arg_id);
190	            let conflicts = conflicts.gather_conflicts(self.p.app, matcher, arg_id);
191	            self.build_conflict_err(arg_id, &conflicts, matcher)?;
192	        }
193	
194	        Ok(())
195	    }
