197	    fn validate_exclusive(&self, matcher: &ArgMatcher) -> ClapResult<()> {
198	        debug!("Validator::validate_exclusive");
199	        let args_count = matcher.arg_names().count();
200	        matcher
201	            .arg_names()
202	            .filter_map(|name| {
203	                debug!("Validator::validate_exclusive:iter:{:?}", name);
204	                self.p
205	                    .app
206	                    .find(name)
207	                    // Find `arg`s which are exclusive but also appear with other args.
208	                    .filter(|&arg| arg.is_set(ArgSettings::Exclusive) && args_count > 1)
209	            })
210	            // Throw an error for the first conflict found.
211	            .try_for_each(|arg| {
212	                Err(Error::argument_conflict(
213	                    self.p.app,
214	                    arg,
215	                    Vec::new(),
216	                    Usage::new(self.p.app, &self.p.required).create_usage_with_title(&[]),
217	                ))
218	            })
219	    }
