221	    fn build_conflict_err(
222	        &self,
223	        name: &Id,
224	        conflict_ids: &[Id],
225	        matcher: &ArgMatcher,
226	    ) -> ClapResult<()> {
227	        if conflict_ids.is_empty() {
228	            return Ok(());
229	        }
230	
231	        debug!("Validator::build_conflict_err: name={:?}", name);
232	        let mut seen = std::collections::HashSet::new();
233	        let conflicts = conflict_ids
234	            .iter()
235	            .flat_map(|c_id| {
236	                if self.p.app.find_group(c_id).is_some() {
237	                    self.p.app.unroll_args_in_group(c_id)
238	                } else {
239	                    vec![c_id.clone()]
240	                }
241	            })
242	            .filter_map(|c_id| {
243	                seen.insert(c_id.clone()).then(|| {
244	                    let c_arg = self.p.app.find(&c_id).expect(INTERNAL_ERROR_MSG);
245	                    c_arg.to_string()
246	                })
247	            })
248	            .collect();
249	
250	        let former_arg = self.p.app.find(name).expect(INTERNAL_ERROR_MSG);
251	        let usg = self.build_conflict_err_usage(matcher, conflict_ids);
252	        Err(Error::argument_conflict(
253	            self.p.app, former_arg, conflicts, usg,
254	        ))
255	    }
256	
257	    fn build_conflict_err_usage(&self, matcher: &ArgMatcher, conflicting_keys: &[Id]) -> String {
258	        let used_filtered: Vec<Id> = matcher
259	            .arg_names()
260	            .filter(|key| !conflicting_keys.contains(key))
261	            .cloned()
262	            .collect();
263	        let required: Vec<Id> = used_filtered
264	            .iter()
265	            .filter_map(|key| self.p.app.find(key))
266	            .flat_map(|arg| arg.requires.iter().map(|item| &item.1))
267	            .filter(|key| !used_filtered.contains(key) && !conflicting_keys.contains(key))
268	            .chain(used_filtered.iter())
269	            .cloned()
270	            .collect();
271	        Usage::new(self.p.app, &self.p.required).create_usage_with_title(&required)
272	    }
