274	    fn gather_requirements(&mut self, matcher: &ArgMatcher) {
275	        debug!("Validator::gather_requirements");
276	        for name in matcher.arg_names() {
277	            debug!("Validator::gather_requirements:iter:{:?}", name);
278	            if let Some(arg) = self.p.app.find(name) {
279	                for req in self
280	                    .p
281	                    .app
282	                    .unroll_requirements_for_arg(&arg.id, Some(matcher))
283	                {
284	                    self.p.required.insert(req);
285	                }
286	            } else if let Some(g) = self.p.app.find_group(name) {
287	                debug!("Validator::gather_requirements:iter:{:?}:group", name);
288	                for r in &g.requires {
289	                    self.p.required.insert(r.clone());
290	                }
291	            }
292	        }
293	    }
