64	impl Config {
65	/// Parse the given pattern and returned its HIR expression along with
66	/// the current configuration.
67	///
68	/// If there was a problem parsing the given expression then an error
69	/// is returned.
70	pub fn hir(&self, pattern: &str) -> Result<ConfiguredHIR, Error> {
71	let ast = self.ast(pattern)?;
72	let analysis = self.analysis(&ast)?;
73	let expr = hir::translate::TranslatorBuilder::new()
74	.allow_invalid_utf8(true)
75	.case_insensitive(self.is_case_insensitive(&analysis))
76	.multi_line(self.multi_line)
77	.dot_matches_new_line(self.dot_matches_new_line)
78	.swap_greed(self.swap_greed)
79	.unicode(self.unicode)
80	.build()
81	.translate(pattern, &ast)
82	.map_err(Error::regex)?;
83	let expr = match self.line_terminator {
84	None => expr,
85	Some(line_term) => strip_from_match(expr, line_term)?,
86	};
87	Ok(ConfiguredHIR {
88	original: pattern.to_string(),
89	config: self.clone(),
90	analysis,
91	// If CRLF mode is enabled, replace `$` with `(?:\r?$)`.
92	expr: if self.crlf { crlfify(expr) } else { expr },
93	})
94	}
95	
96	/// Accounting for the `smart_case` config knob, return true if and only if
97	/// this pattern should be matched case insensitively.
98	fn is_case_insensitive(&self, analysis: &AstAnalysis) -> bool {
99	if self.case_insensitive {
100	return true;
101	}
102	if !self.case_smart {
103	return false;
104	}
105	analysis.any_literal() && !analysis.any_uppercase()
106	}
107	
108	/// Returns true if and only if this config is simple enough such that
109	/// if the pattern is a simple alternation of literals, then it can be
110	/// constructed via a plain Aho-Corasick automaton.
111	///
112	/// Note that it is OK to return true even when settings like `multi_line`
113	/// are enabled, since if multi-line can impact the match semantics of a
114	/// regex, then it is by definition not a simple alternation of literals.
115	pub fn can_plain_aho_corasick(&self) -> bool {
116	!self.word && !self.case_insensitive && !self.case_smart
117	}
118	
119	/// Perform analysis on the AST of this pattern.
120	///
121	/// This returns an error if the given pattern failed to parse.
122	fn analysis(&self, ast: &Ast) -> Result<AstAnalysis, Error> {
123	Ok(AstAnalysis::from_ast(ast))
124	}
125	
126	/// Parse the given pattern into its abstract syntax.
127	///
128	/// This returns an error if the given pattern failed to parse.
129	fn ast(&self, pattern: &str) -> Result<Ast, Error> {
130	ast::parse::ParserBuilder::new()
131	.nest_limit(self.nest_limit)
132	.octal(self.octal)
133	.ignore_whitespace(self.ignore_whitespace)
134	.build()
135	.parse(pattern)
136	.map_err(Error::regex)
137	}
138	}
