140	/// A "configured" HIR expression, which is aware of the configuration which
141	/// produced this HIR.
142	///
143	/// Since the configuration is tracked, values with this type can be
144	/// transformed into other HIR expressions (or regular expressions) in a way
145	/// that preserves the configuration. For example, the `fast_line_regex`
146	/// method will apply literal extraction to the inner HIR and use that to build
147	/// a new regex that matches the extracted literals in a way that is
148	/// consistent with the configuration that produced this HIR. For example, the
149	/// size limits set on the configured HIR will be propagated out to any
150	/// subsequently constructed HIR or regular expression.
151	#[derive(Clone, Debug)]
152	pub struct ConfiguredHIR {
153	original: String,
154	config: Config,
155	analysis: AstAnalysis,
156	expr: Hir,
157	}
158	
159	impl ConfiguredHIR {
160	/// Return the configuration for this HIR expression.
161	pub fn config(&self) -> &Config {
162	&self.config
163	}
164	
165	/// Compute the set of non-matching bytes for this HIR expression.
166	pub fn non_matching_bytes(&self) -> ByteSet {
167	non_matching_bytes(&self.expr)
168	}
169	
170	/// Returns true if and only if this regex needs to have its match offsets
171	/// tweaked because of CRLF support. Specifically, this occurs when the
172	/// CRLF hack is enabled and the regex is line anchored at the end. In
173	/// this case, matches that end with a `\r` have the `\r` stripped.
174	pub fn needs_crlf_stripped(&self) -> bool {
175	self.config.crlf && self.expr.is_line_anchored_end()
