177	
178	/// Returns the line terminator configured on this expression.
179	///
180	/// When we have beginning/end anchors (NOT line anchors), the fast line
181	/// searching path isn't quite correct. Or at least, doesn't match the
182	/// slow path. Namely, the slow path strips line terminators while the
183	/// fast path does not. Since '$' (when multi-line mode is disabled)
184	/// doesn't match at line boundaries, the existence of a line terminator
185	/// might cause it to not match when it otherwise would with the line
186	/// terminator stripped.
187	///
188	/// Since searching with text anchors is exceptionally rare in the
189	/// context of line oriented searching (multi-line mode is basically
190	/// always enabled), we just disable this optimization when there are
191	/// text anchors. We disable it by not returning a line terminator, since
192	/// without a line terminator, the fast search path can't be executed.
193	///
194	/// See: <https://github.com/BurntSushi/ripgrep/issues/2260>
195	pub fn line_terminator(&self) -> Option<LineTerminator> {
196	if self.is_any_anchored() {
197	None
198	} else {
199	self.config.line_terminator
200	}
201	}
202	
203	/// Returns true if and only if the underlying HIR has any text anchors.
204	fn is_any_anchored(&self) -> bool {
205	self.expr.is_any_anchored_start() || self.expr.is_any_anchored_end()
206	}
207	
208	/// Builds a regular expression from this HIR expression.
209	pub fn regex(&self) -> Result<Regex, Error> {
210	self.pattern_to_regex(&self.expr.to_string())
211	}
212	
213	/// If this HIR corresponds to an alternation of literals with no
214	/// capturing groups, then this returns those literals.
215	pub fn alternation_literals(&self) -> Option<Vec<Vec<u8>>> {
216	if !self.config.can_plain_aho_corasick() {
217	return None;
218	}
219	alternation_literals(&self.expr)
220	}
