222	/// Applies the given function to the concrete syntax of this HIR and then
223	/// generates a new HIR based on the result of the function in a way that
224	/// preserves the configuration.
225	///
226	/// For example, this can be used to wrap a user provided regular
227	/// expression with additional semantics. e.g., See the `WordMatcher`.
228	pub fn with_pattern<F: FnMut(&str) -> String>(
229	&self,
230	mut f: F,
231	) -> Result<ConfiguredHIR, Error> {
232	self.pattern_to_hir(&f(&self.expr.to_string()))
233	}
