235	/// If the current configuration has a line terminator set and if useful
236	/// literals could be extracted, then a regular expression matching those
237	/// literals is returned. If no line terminator is set, then `None` is
238	/// returned.
239	///
240	/// If compiling the resulting regular expression failed, then an error
241	/// is returned.
242	///
243	/// This method only returns something when a line terminator is set
244	/// because matches from this regex are generally candidates that must be
245	/// confirmed before reporting a match. When performing a line oriented
246	/// search, confirmation is easy: just extend the candidate match to its
247	/// respective line boundaries and then re-search that line for a full
248	/// match. This only works when the line terminator is set because the line
249	/// terminator setting guarantees that the regex itself can never match
250	/// through the line terminator byte.
251	pub fn fast_line_regex(&self) -> Result<Option<Regex>, Error> {
252	if self.config.line_terminator.is_none() {
253	return Ok(None);
254	}
255	match LiteralSets::new(&self.expr).one_regex(self.config.word) {
256	None => Ok(None),
257	Some(pattern) => self.pattern_to_regex(&pattern).map(Some),
258	}
259	}
