296	/// Create an HIR expression from the given pattern using this HIR's
297	/// configuration.
298	fn pattern_to_hir(&self, pattern: &str) -> Result<ConfiguredHIR, Error> {
299	// See `pattern_to_regex` comment for explanation of why we only set
300	// a subset of knobs here. e.g., `swap_greed` is explicitly left out.
301	let expr = ::regex_syntax::ParserBuilder::new()
302	.nest_limit(self.config.nest_limit)
303	.octal(self.config.octal)
304	.allow_invalid_utf8(true)
305	.multi_line(self.config.multi_line)
306	.dot_matches_new_line(self.config.dot_matches_new_line)
307	.unicode(self.config.unicode)
308	.build()
309	.parse(pattern)
310	.map_err(Error::regex)?;
311	Ok(ConfiguredHIR {
312	original: self.original.clone(),
313	config: self.config.clone(),
314	analysis: self.analysis.clone(),
315	expr,
316	})
317	}
