44	    /// <https://docs.rs/regex/#syntax>.
45	    pub fn build(&self, pattern: &str) -> Result<RegexMatcher, Error> {
46	        let chir = self.config.hir(pattern)?;
47	        let fast_line_regex = chir.fast_line_regex()?;
48	        let non_matching_bytes = chir.non_matching_bytes();
49	        if let Some(ref re) = fast_line_regex {
50	            log::debug!("extracted fast line regex: {:?}", re);
51	        }
