53	        let matcher = RegexMatcherImpl::new(&chir)?;
54	        log::trace!("final regex: {:?}", matcher.regex());
55	        let mut config = self.config.clone();
56	        // We override the line terminator in case the configured expr doesn't
57	        // support it.
58	        config.line_terminator = chir.line_terminator();
59	        Ok(RegexMatcher {
60	            config,
61	            matcher,
62	            fast_line_regex,
63	            non_matching_bytes,
64	        })
65	    }
