67	    /// Build a new matcher from a plain alternation of literals.
68	    ///
69	    /// Depending on the configuration set by the builder, this may be able to
70	    /// build a matcher substantially faster than by joining the patterns with
71	    /// a `|` and calling `build`.
72	    pub fn build_literals<B: AsRef<str>>(
73	        &self,
