121	// chooseCodespaceFromList returns the codespace that the user has interactively selected from the list, or
122	// an error if there are no codespaces.
123	func chooseCodespaceFromList(ctx context.Context, codespaces []*api.Codespace, includeOwner bool) (*api.Codespace, error) {
124	if len(codespaces) == 0 {
125	return nil, errNoCodespaces
126	}
127	
128	sortedCodespaces := codespaces
129	sort.Slice(sortedCodespaces, func(i, j int) bool {
130	return sortedCodespaces[i].CreatedAt > sortedCodespaces[j].CreatedAt
131	})
132	
133	csSurvey := []*survey.Question{
134	{
135	Name: "codespace",
136	Prompt: &survey.Select{
137	Message: "Choose codespace:",
138	Options: formatCodespacesForSelect(sortedCodespaces, includeOwner),
139	},
140	Validate: survey.Required,
141	},
142	}
143	
144	var answers struct {
145	Codespace int
146	}
147	if err := ask(csSurvey, &answers); err != nil {
148	return nil, fmt.Errorf("error getting answers: %w", err)
149	}
150	
151	return sortedCodespaces[answers.Codespace], nil
152	}
