168	func getOrChooseCodespace(ctx context.Context, apiClient apiClient, codespaceName string) (codespace *api.Codespace, err error) {
169	if codespaceName == "" {
170	codespace, err = chooseCodespace(ctx, apiClient)
171	if err != nil {
