194	func safeClose(closer io.Closer, err *error) {
195	if closeErr := closer.Close(); *err == nil {
196	*err = closeErr
197	}
198	}
199	
200	// hasTTY indicates whether the process connected to a terminal.
201	// It is not portable to assume stdin/stdout are fds 0 and 1.
202	var hasTTY = term.IsTerminal(int(os.Stdin.Fd())) && term.IsTerminal(int(os.Stdout.Fd()))
203	
204	// ask asks survey questions on the terminal, using standard options.
205	// It fails unless hasTTY, but ideally callers should avoid calling it in that case.
206	func ask(qs []*survey.Question, response interface{}) error {
207	if !hasTTY {
208	return fmt.Errorf("no terminal")
209	}
210	err := survey.Ask(qs, response, survey.WithShowCursor(true))
211	// The survey package temporarily clears the terminal's ISIG mode bit
212	// (see tcsetattr(3)) so the QUIT button (Ctrl-C) is reported as
213	// ASCII \x03 (ETX) instead of delivering SIGINT to the application.
214	// So we have to serve ourselves the SIGINT.
215	//
216	// https://github.com/AlecAivazis/survey/#why-isnt-ctrl-c-working
217	if err == terminal.InterruptErr {
218	self, _ := os.FindProcess(os.Getpid())
219	_ = self.Signal(os.Interrupt) // assumes POSIX
220	
221	// Suspend the goroutine, to avoid a race between
222	// return from main and async delivery of INT signal.
223	select {}
224	}
225	return err
226	}
