282	func wrapLevelWithColor(level string) string {
283	var colour color.Color
284	switch level {
285	case levelAlert:
286	colour = color.FgRed
287	case levelError:
288	colour = color.FgRed
289	case levelFatal:
290	colour = color.FgRed
291	case levelInfo:
292	colour = color.FgBlue
293	case levelSlow:
294	colour = color.FgYellow
295	case levelDebug:
296	colour = color.FgYellow
297	case levelStat:
298	colour = color.FgGreen
299	}
300	
301	if colour == color.NoColor {
