321	switch v := val.(type) {
322	case string:
323	writePlainText(writer, level, v, fields...)
324	case error:
325	writePlainText(writer, level, v.Error(), fields...)
326	case fmt.Stringer:
327	writePlainText(writer, level, v.String(), fields...)
328	default:
329	writePlainValue(writer, level, v, fields...)
330	}
