369	buf.WriteString(item)
370	}
371	buf.WriteByte('\n')
372	if writer == nil {
373	log.Println(buf.String())
374	return
375	}
376	
377	if _, err := writer.Write(buf.Bytes()); err != nil {
378	log.Println(err.Error())
379	}
380	}
