339	/* a single CCtx Pool can be invoked from multiple threads in parallel */
340	
341	typedef struct {
342	    ZSTD_pthread_mutex_t poolMutex;
343	    int totalCCtx;
344	    int availCCtx;
345	    ZSTD_customMem cMem;
346	    ZSTD_CCtx* cctx[1];   /* variable size */
347	} ZSTDMT_CCtxPool;
