369	/* Consume the specified number of characters from our source.
370	 * Only the first character may be a newline.
371	 */
372	static void consume_chars(lexer_t* lexer, size_t count)
373	{
374	  assert(lexer->len >= count);
375	
376	  if(count == 0)
377	    return;
378	
379	  if(lexer->source->m[lexer->ptr] == '\n')
380	  {
381	    lexer->line++;
382	    lexer->pos = 0;
383	  }
384	
385	  lexer->ptr += count;
386	  lexer->len -= count;
387	  lexer->pos += count;
388	}
