390	
391	// Look at the next unused character in our source, without consuming it
392	static char look(lexer_t* lexer)
393	{
394	  if(is_eof(lexer))
395	    return '\0';
396	
397	  return lexer->source->m[lexer->ptr];
398	}
399	
400	
401	// look(lexer) is equivalent to lookn(lexer, 1)
402	static char lookn(lexer_t* lexer, size_t chars)
403	{
404	  if(lexer->len < chars)
405	    return '\0';
406	
407	  return lexer->source->m[lexer->ptr + chars - 1];
408	}
