411	// Report that the current literal token doesn't terminate
412	static token_t* literal_doesnt_terminate(lexer_t* lexer)
413	{
414	  lex_error(lexer, "Literal doesn't terminate");
415	  lexer->ptr += lexer->len;
416	  lexer->len = 0;
417	  return make_token(lexer, TK_LEX_ERROR);
