420	
421	// Process a block comment the leading / * for which has been seen, but not
422	// consumed
423	static token_t* nested_comment(lexer_t* lexer)
424	{
425	  consume_chars(lexer, 2); // Leading / *
426	  size_t depth = 1;
427	
428	  while(depth > 0)
429	  {
430	    if(lexer->len <= 1)
431	    {
432	      lex_error(lexer, "Nested comment doesn't terminate");
433	      lexer->ptr += lexer->len;
434	      lexer->len = 0;
435	      return make_token(lexer, TK_LEX_ERROR);
436	    }
437	
438	    if(look(lexer) == '*' && lookn(lexer, 2) == '/')
439	    {
440	      consume_chars(lexer, 2);
441	      depth--;
442	    }
443	    else if(look(lexer) == '/' && lookn(lexer, 2) == '*')
444	    {
445	      consume_chars(lexer, 2);
446	      depth++;
447	    }
448	    else
449	    {
450	      consume_chars(lexer, 1);
451	    }
452	  }
453	
454	  lexer->newline = false;
455	  return NULL;
456	}
