458	
459	// Process a line comment the leading // for which has been seen, but not
460	// consumed
461	static token_t* line_comment(lexer_t* lexer)
462	{
463	  consume_chars(lexer, 2); // Leading //
464	
465	  // We don't consume the terminating newline here, but it will be handled next
466	  // as whitespace
467	  while(!is_eof(lexer) && (look(lexer) != '\n'))
468	    consume_chars(lexer, 1);
469	
470	  return NULL;
471	}
472	
473	
474	// Process a slash, which has been seen, but not consumed
475	static token_t* slash(lexer_t* lexer)
476	{
477	  if(lookn(lexer, 2) == '*')
478	    return nested_comment(lexer);
479	
480	  if(lookn(lexer, 2) == '/')
481	    return line_comment(lexer);
482	
483	  consume_chars(lexer, 1);
484	  return make_token(lexer, TK_DIVIDE);
485	}
