488	/**
489	* Removes longest common prefix indentation from every line in a triple
490	* quoted string. If the string begins with an empty line, that line is removed
491	* entirely.
492	*/
493	static void normalise_string(lexer_t* lexer)
494	{
495	  if(lexer->buflen == 0)
496	    return;
497	
498	  // If we aren't multiline, do nothing.
499	  if(memchr(lexer->buffer, '\n', lexer->buflen) == NULL)
500	    return;
501	
502	  // Calculate leading whitespace.
503	  char* buf = lexer->buffer;
504	  size_t ws = lexer->buflen;
505	  size_t ws_this_line = 0;
506	  bool in_leading_ws = true;
507	
508	  for(size_t i = 0; i < lexer->buflen; i++)
509	  {
510	    char c = lexer->buffer[i];
511	
512	    if(in_leading_ws)
513	    {
514	      if(c == ' ' || c == '\t')
515	      {
516	        ws_this_line++;
517	      }
518	      else if((c != '\r') && (c != '\n'))
519	      {
520	        if(ws_this_line < ws)
521	          ws = ws_this_line;
522	
523	        in_leading_ws = false;
524	      }
525	    }
526	
527	    if(c == '\n')
528	    {
529	      ws_this_line = 0;
530	      in_leading_ws = true;
531	    }
532	  }
533	
534	  // Trim leading whitespace on each line.
535	  if(ws > 0)
536	  {
537	    char* line_start = lexer->buffer;
538	    char* compacted = lexer->buffer;
539	    size_t rem = lexer->buflen;
540	
541	    while(rem > 0)
542	    {
543	      char* line_end = (char*)memchr(line_start, '\n', rem);
544	      size_t line_len =
545	        (line_end == NULL) ? rem : (size_t)(line_end - line_start + 1);
546	
547	      if(line_start != line_end)
548	      {
549	        size_t trim = (line_len < ws) ? line_len : ws;
550	        memmove(compacted, line_start + trim, line_len - trim);
551	        compacted += line_len - trim;
552	      }
553	      else
554	      {
555	        memmove(compacted, line_start, line_len);
556	        compacted += line_len;
557	      }
558	
559	      line_start += line_len;
560	      rem -= line_len;
561	    }
562	
563	    lexer->buflen = compacted - lexer->buffer;
564	  }
565	
566	  // Trim a leading newline if there is one.
567	  buf = lexer->buffer;
568	
569	  if((buf[0] == '\r') && (buf[1] == '\n'))
570	  {
571	    lexer->buflen -= 2;
572	    memmove(&buf[0], &buf[2], lexer->buflen);
573	  }
574	  else if(buf[0] == '\n')
575	  {
576	    lexer->buflen--;
577	    memmove(&buf[0], &buf[1], lexer->buflen);
578	  }
579	}
