581	
582	// Process a triple quoted string, the leading """ of which has been seen, but
583	// not consumed
584	static token_t* triple_string(lexer_t* lexer)
585	{
586	  consume_chars(lexer, 3);  // Leading """
587	
588	  while(true)
589	  {
590	    if(is_eof(lexer))
591	      return literal_doesnt_terminate(lexer);
592	
593	    char c = look(lexer);
594	
595	    if((c == '\"') && (lookn(lexer, 2) == '\"') && (lookn(lexer, 3) == '\"'))
596	    {
597	      consume_chars(lexer, 3);
598	
599	      // Triple strings can end with 3 or more "s. If there are more than 3
600	      // the extra ones are part of the string contents
601	      while(look(lexer) == '\"')
602	      {
603	        append_to_token(lexer, '\"');
604	        consume_chars(lexer, 1);
605	      }
606	
607	      normalise_string(lexer);
608	      return make_token_with_text(lexer, TK_STRING);
609	    }
610	
611	    consume_chars(lexer, 1);
612	    append_to_token(lexer, c);
613	  }
614	}
