617	// Read a hex or unicode escape sequence, for which the leading \x has been
618	// consumed.
619	// The length specified is the number of hex digits expected.
620	// On success return the unicode value.
621	// On error return minus the number of characters processed (including the \x)
622	// and do not report an error.
623	static int read_hex_escape(lexer_t* lexer, int length)
624	{
625	  uint32_t value = 0;
626	
627	  int text_len = 2; // start with "\x"
628	
629	  for(int i = 0; i < length; i++)
630	  {
631	    char c = look(lexer);
632	    int digit = 0;
633	
634	    if((c >= '0') && (c <= '9'))
635	      digit = c - '0';
636	    else if((c >= 'a') && (c <= 'f'))
637	      digit = c + 10 - 'a';
638	    else if((c >= 'A') && (c <= 'F'))
639	      digit = c + 10 - 'A';
640	    else
641	      return -text_len;
642	
643	    text_len++;
644	    consume_chars(lexer, 1);
645	    value = (value << 4) + digit;
646	  }
647	
648	  return value;
649	}
