31	// ccResolverWrapper is a wrapper on top of cc for resolvers.
32	// It implements resolver.ClientConnection interface.
33	type ccResolverWrapper struct {
34	cc       *ClientConn
35	resolver resolver.Resolver
36	done     uint32 // accessed atomically; set to 1 when closed.
37	curState resolver.State
38	}
39	
40	// split2 returns the values from strings.SplitN(s, sep, 2).
41	// If sep is not found, it returns ("", "", false) instead.
42	func split2(s, sep string) (string, string, bool) {
43	spl := strings.SplitN(s, sep, 2)
44	if len(spl) < 2 {
45	return "", "", false
46	}
47	return spl[0], spl[1], true
48	}
49	
50	// parseTarget splits target into a struct containing scheme, authority and
51	// endpoint.
52	//
53	// If target is not a valid scheme://authority/endpoint, it returns {Endpoint:
54	// target}.
55	func parseTarget(target string) (ret resolver.Target) {
56	var ok bool
57	ret.Scheme, ret.Endpoint, ok = split2(target, "://")
58	if !ok {
59	return resolver.Target{Endpoint: target}
60	}
61	ret.Authority, ret.Endpoint, ok = split2(ret.Endpoint, "/")
62	if !ok {
63	return resolver.Target{Endpoint: target}
64	}
65	return ret
66	}
67	
68	// newCCResolverWrapper parses cc.target for scheme and gets the resolver
69	// builder for this scheme and builds the resolver. The monitoring goroutine
70	// for it is not started yet and can be created by calling start().
71	//
72	// If withResolverBuilder dial option is set, the specified resolver will be
73	// used instead.
74	func newCCResolverWrapper(cc *ClientConn) (*ccResolverWrapper, error) {
75	rb := cc.dopts.resolverBuilder
76	if rb == nil {
77	return nil, fmt.Errorf("could not get resolver for scheme: %q", cc.parsedTarget.Scheme)
78	}
79	
80	ccr := &ccResolverWrapper{cc: cc}
81	
82	var err error
83	ccr.resolver, err = rb.Build(cc.parsedTarget, ccr, resolver.BuildOption{DisableServiceConfig: cc.dopts.disableServiceConfig})
84	if err != nil {
85	return nil, err
86	}
87	return ccr, nil
88	}
