103	func (ccr *ccResolverWrapper) UpdateState(s resolver.State) {
104	if ccr.isDone() {
105	return
106	}
107	grpclog.Infof("ccResolverWrapper: sending update to cc: %v", s)
108	if channelz.IsOn() {
109	ccr.addChannelzTraceEvent(s)
110	}
111	ccr.cc.updateResolverState(s)
112	ccr.curState = s
113	}
