115	// NewAddress is called by the resolver implementation to send addresses to gRPC.
116	func (ccr *ccResolverWrapper) NewAddress(addrs []resolver.Address) {
117	if ccr.isDone() {
118	return
119	}
120	grpclog.Infof("ccResolverWrapper: sending new addresses to cc: %v", addrs)
121	if channelz.IsOn() {
122	ccr.addChannelzTraceEvent(resolver.State{Addresses: addrs, ServiceConfig: ccr.curState.ServiceConfig})
123	}
124	ccr.curState.Addresses = addrs
125	ccr.cc.updateResolverState(ccr.curState)
126	}
127	
128	// NewServiceConfig is called by the resolver implementation to send service
129	// configs to gRPC.
130	func (ccr *ccResolverWrapper) NewServiceConfig(sc string) {
131	if ccr.isDone() {
132	return
133	}
134	grpclog.Infof("ccResolverWrapper: got new service config: %v", sc)
135	c, err := parseServiceConfig(sc)
136	if err != nil {
137	return
138	}
139	if channelz.IsOn() {
140	ccr.addChannelzTraceEvent(resolver.State{Addresses: ccr.curState.Addresses, ServiceConfig: c})
141	}
142	ccr.curState.ServiceConfig = c
143	ccr.cc.updateResolverState(ccr.curState)
144	}
145	
146	func (ccr *ccResolverWrapper) addChannelzTraceEvent(s resolver.State) {
147	var updates []string
148	oldSC, oldOK := ccr.curState.ServiceConfig.(*ServiceConfig)
149	newSC, newOK := s.ServiceConfig.(*ServiceConfig)
150	if oldOK != newOK || (oldOK && newOK && oldSC.rawJSONString != newSC.rawJSONString) {
151	updates = append(updates, "service config updated")
152	}
153	if len(ccr.curState.Addresses) > 0 && len(s.Addresses) == 0 {
154	updates = append(updates, "resolver returned an empty address list")
155	} else if len(ccr.curState.Addresses) == 0 && len(s.Addresses) > 0 {
156	updates = append(updates, "resolver returned new addresses")
157	}
158	channelz.AddTraceEvent(ccr.cc.channelzID, &channelz.TraceEventDesc{
159	Desc:     fmt.Sprintf("Resolver state updated: %+v (%v)", s, strings.Join(updates, "; ")),
160	Severity: channelz.CtINFO,
161	})
