	name: 'Normalize topic thumbnails, post & user uploads to same format',
	timestamp: Date.UTC(2025, 3, 4),
	method: async function () {
		const { progress } = this;

		const [topicCount, postCount, userCount] = await db.sortedSetsCard(['topics:tid', 'posts:pid', 'users:joindate']);
		progress.total = topicCount + postCount + userCount;

		function normalizePath(path) {
			if (path.startsWith('http')) {
				return path;
			}
			path = path.replace(/\\/g, '/');
			if (!path.startsWith('/')) {
				path = `/${path}`;
			}
			return path;
		}
	}"}, {"file": "src/upgrades/4.3.0/topic_follower_counts.js", "start_line": 7, "end_line": 35, "content": "module.exports = {
	name: 'Set "followercount" on each topic object',
	timestamp: Date.UTC(2025, 3, 15),
	method: async function () {
		const { progress } = this;

		progress.total = await db.sortedSetCard('topics:tid');

		await batch.processSortedSet('topics:tid', async (tids) => {
			const keys = tids.map(tid => `tid:${tid}:followers`);
			const followerCounts = await db.setsCount(keys);

			const bulkSet = [];

			followerCounts.forEach((count, idx) => {
				const tid = tids[idx];
				if (count > 0) {
					bulkSet.push([`topic:${tid}`, {followercount: count}]);
				}
			});

			await db.setObjectBulk(bulkSet);

			progress.incr(tids.length);
		}, {
			batch: 500,
		});
	},
};"}, {"file": "src/user/settings.js", "start_line": 50, "end_line": 93, "content": "async function onSettingsLoaded(uid, settings) {
