3	// Script variables.
4	
5	// Count the number of GitHub API tokens available.
6	const PATs = Object.keys(process.env).filter((key) =>
7	/PAT_\d*$/.exec(key),
8	).length;
9	const RETRIES = process.env.NODE_ENV === "test" ? 7 : PATs;
10	
11	/**
12	* @typedef {import("axios").AxiosResponse} AxiosResponse Axios response.
13	* @typedef {(variables: object, token: string) => Promise<AxiosResponse>} FetcherFunction Fetcher function.
14	*/
15	
16	/**
17	* Try to execute the fetcher function until it succeeds or the max number of retries is reached.
18	*
19	* @param {FetcherFunction} fetcher The fetcher function.
20	* @param {object} variables Object with arguments to pass to the fetcher function.
21	* @param {number} retries How many times to retry.
22	* @returns {Promise<T>} The response from the fetcher function.
23	*/
24	const retryer = async (fetcher, variables, retries = 0) => {
25	if (!RETRIES) {
26	throw new CustomError("No GitHub API tokens found", CustomError.NO_TOKENS);
27	}
28	if (retries > RETRIES) {
29	throw new CustomError(
30	"Downtime due to GitHub API rate limiting",
31	CustomError.MAX_RETRY,
32	);
33	}
34	try {
35	// try to fetch with the first token since RETRIES is 0 index i'm adding +1
36	let response = await fetcher(
37	variables,
38	process.env[`PAT_${retries + 1}`],
39	retries,
40	);
41	
42	// prettier-ignore
43	const isRateExceeded = response.data.errors && response.data.errors[0].type === "RATE_LIMITED";
44	
45	// if rate limit is hit increase the RETRIES and recursively call the retryer
46	// with username, and current RETRIES
47	if (isRateExceeded) {
48	logger.log(`PAT_${retries + 1} Failed`);
49	retries++;
50	// directly return from the function
51	return retryer(fetcher, variables, retries);
52	}
53	
54	// finally return the response
55	return response;
56	} catch (err) {
57	// prettier-ignore
58	// also checking for bad credentials if any tokens gets invalidated
59	const isBadCredential = err.response.data && err.response.data.message === "Bad credentials";
60	const isAccountSuspended =
61	err.response.data &&
62	err.response.data.message === "Sorry. Your account was suspended.";
63	
64	if (isBadCredential || isAccountSuspended) {
65	logger.log(`PAT_${retries + 1} Failed`);
66	retries++;
67	// directly return from the function
68	return retryer(fetcher, variables, retries);
69	} else {
70	return err.response;
71	}
72	}
73	};
74	
75	export { retryer, RETRIES };
76	export default retryer;
