303	inline std::ostream& minifier<dom::element>::print(std::ostream& out) {
304	using tape_type=internal::tape_type;
305	size_t depth = 0;
306	constexpr size_t MAX_DEPTH = 16;
307	bool is_object[MAX_DEPTH];
308	is_object[0] = false;
309	bool after_value = false;
310	
311	internal::tape_ref iter(value);
312	do {
