314	if (after_value) {
315	out << ",";
316	}
317	// If we are in an object, print the next key and :, and skip to the next value.
318	if (is_object[depth]) {
319	out << '"' << internal::escape_json_string(iter.get_string_view()) << "\":";
320	iter.json_index++;
