322	switch (iter.tape_ref_type()) {
323	
324	// Arrays
325	case tape_type::START_ARRAY: {
326	// If we're too deep, we need to recurse to go deeper.
327	depth++;
328	if (unlikely(depth >= MAX_DEPTH)) {
329	out << minify<dom::array>(dom::array(iter.doc, iter.json_index));
330	iter.json_index = iter.matching_brace_index() - 1; // Jump to the ]
331	depth--;
332	break;
333	}
334	
335	// Output start [
336	out << '[';
337	iter.json_index++;
338	
339	// Handle empty [] (we don't want to come back around and print commas)
340	if (iter.tape_ref_type() == tape_type::END_ARRAY) {
341	out << ']';
342	depth--;
343	break;
344	}
345	
346	is_object[depth] = false;
347	after_value = false;
348	continue;
349	}
350	
351	// Objects
352	case tape_type::START_OBJECT: {
353	// If we're too deep, we need to recurse to go deeper.
354	depth++;
355	if (unlikely(depth >= MAX_DEPTH)) {
356	out << minify<dom::object>(dom::object(iter.doc, iter.json_index));
357	iter.json_index = iter.matching_brace_index() - 1; // Jump to the }
358	depth--;
359	break;
360	}
361	
362	// Output start {
363	out << '{';
364	iter.json_index++;
365	
366	// Handle empty {} (we don't want to come back around and print commas)
367	if (iter.tape_ref_type() == tape_type::END_OBJECT) {
368	out << '}';
369	depth--;
